import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.BitSet;
import java.util.List;

public class hashprime {
    public static void main(String[] args) {
        if (args.length == 0) {
            System.out.println("Usage: java hashprime <N>");
            System.out.println("Computes the SHA-256 hash of all primes <= N (newline-terminated).");
            return;
        }

        int n = 0;
        try {
            n = Integer.parseInt(args[0]);
        } catch (NumberFormatException e) {
            System.out.println("Usage: java hashprime <N>");
            System.out.println("Computes the SHA-256 hash of all primes <= N (newline-terminated).");
            return;
        }

        // For N < 2, empty byte stream gives SHA-256 of empty string
        if (n < 2) {
            try (MessageDigest md = MessageDigest.getInstance("SHA-256")) {
                String hash = bytesToHex(md.digest(new byte[0]));
                System.out.println(hash);
            } catch (NoSuchAlgorithmException e) {
                throw new RuntimeException(e);
            }
            return;
        }

        // Generate primes up to N using segmented sieve with wheel optimization
        List<Integer> primes = generatePrimes(n);

        // Compute SHA-256 hash incrementally
        try (MessageDigest md = MessageDigest.getInstance("SHA-256")) {
            byte[] primeBytes = new byte[primes.size()];

            for (int i = 0; i < primes.size(); i++) {
                int p = primes.get(i);
                String decimalStr = Integer.toString(p);
                byte[] numBytes = toByteArray(decimalStr + '\n');

                // Add bytes directly to the digest's buffer, but we need incremental update
                md.update(numBytes);
            }

            String hash = bytesToHex(md.digest());
            System.out.println(hash);
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    // Generate all primes up to n using segmented sieve with 30-wheel optimization
    public static List<Integer> generatePrimes(int n) {
        if (n < 2) {
            return List.of();
        }

        List<Integer> primes = new ArrayList<>();

        // Handle small primes separately
        if (n >= 2) {
            primes.add(2);
        }
        if (n >= 3) {
            primes.add(3);
        }

        int limit = (int) Math.sqrt(n);
        List<Integer> basePrimes = new ArrayList<>();

        // Generate base primes up to sqrt(n) using simple sieve
        if (limit >= 5) {
            BitSet smallIsPrime = new BitSet(limit + 1);
            for (int i = 0; i <= limit; i++) {
                smallIsPrime.set(i, true);
            }
            smallIsPrime.clear(0);
            smallIsPrime.clear(1);
            smallIsPrime.clear(2); // already added

            for (int i = 3; i <= limit; i += 2) {
                if (smallIsPrime.get(i)) {
                    basePrimes.add(i);
                    for (int j = i * i; j <= limit; j += 2 * i) {
                        smallIsPrime.set(j, false);
                    }
                }
            }

            // Re-add 2
            basePrimes.add(0);
        } else if (limit >= 3) {
            basePrimes.add(2);
            if (limit >= 5) {
                basePrimes.add(3);
            }
        }

        int segmentSize = Math.min(n, 48_000); // Cache-friendly size

        for (int low = 5; low <= n; low += 30) {
            int high = Math.min(low + segmentSize - 1, n);
            if (high < low) {
                high = low;
            }

            // Use wheel to mark composite in segment [low, high]
            boolean[] isComposite = new boolean[high - low + 1];

            for (int p : basePrimes) {
                if ((long)p * p > high) {
                    break;
                }

                // Find first multiple of p >= low and in the range
                int start = (low + p - 1) / p * p;
                if (start < low) {
                    start = low;
                }
                if (start % 2 == 0) {
                    start++; // Skip even multiples
                }
                if ((long)p * p <= high && start < p * p) {
                    start = p * p;
                }

                for (int i = (int)Math.max(start, low); i <= high; i += p) {
                    isComposite[i - low] = true;
                }
            }

            // Collect primes in this segment using 30-wheel residues: [1, 7, 11, 13, 17, 19, 23, 29]
            int wheelStep = 30;
            for (int candidate : getWheelResidues()) {
                int check = low + candidate - (low % 30);
                while (check < low) {
                    check += 30;
                }

                while (check <= high) {
                    if (!isComposite[check - low]) {
                        // Check primality (should always be prime here after sieving)
                        boolean isPrime = true;
                        for (int baseP : basePrimes) {
                            if ((long)p * p > check) {
                                break;
                            }
                            if (check % baseP == 0) {
                                isPrime = false;
                                break;
                            }
                        }
                        if (isPrime && check <= n) {
                            primes.add(check);
                        }
                    }
                    check += wheelStep;
                }
            }
        }

        return primes;
    }

    public static List<Integer> getWheelResidues() {
        // 30-wheel: numbers not divisible by 2, 3, 5
        List<Integer> residues = new ArrayList<>();
        residues.add(1);
        residues.add(7);
        residues.add(11);
        residues.add(13);
        residues.add(17);
        residues.add(19);
        residues.add(23);
        residues.add(29);
        return residues;
    }

    public static byte[] toByteArray(String s) {
        byte[] b = new byte[s.length()];
        for (int i = 0; i < s.length(); i++) {
            b[i] = (byte)s.charAt(i);
        }
        return b;
    }

    public static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder(bytes.length * 2);
        for (byte b : bytes) {
            sb.append(((b & 0xFF) / 16)).append("x");
        }
        return sb.toString();
    }
}
